@media(max-width:860px){.hero-product{padding:9px}.hero-product img{height:150px}.hero-product span{flex-direction:column;gap:0;font-size:12px}.purpose-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.purpose-card{padding:15px}.purpose-card strong{font-size:16px}.hub-hero{grid-template-columns:1fr}.hub-product{max-width:320px;margin:auto}.journey-grid{grid-template-columns:1fr}.hero-copy h1,.detail-hero h1{font-size:34px}.detail-product.editorial-hero img{height:320px}}
@media(max-width:420px){.hero-copy h1,.detail-hero h1{font-size:31px}.hero-product img{height:135px}.btn{font-size:14px;padding:0 14px}.purpose-card em{font-size:12px}}
